  });
  console.log(`\nInstance: ${instance}`);

  // Validate the app selection before anything expensive happens.
  selectDevServers(options.apps);

  const stateDir = stateDirFor(instance);
  const envFile = envFileFor(instance);
  const seededMarker = seededMarkerFor(instance);
  const realmHashMarker = realmHashMarkerFor(instance);

  if (options.fresh) {
    clearFreshState({ seededMarker, realmHashMarker });
    if (existsSync(envFile)) {
      // The shared proxy still holds an endpoint on this instance's network — detach before
      // asking Docker to delete it, exactly like `reset` does. Skipping this asks Docker to
      // delete a network with a live endpoint: at best it warns and leaks the network, at worst
      // compose exits non-zero and `--fresh` fails outright.
      await detachInstance({ instance, exec: run });
      await compose(instance, ['down', '-v']);
    }
  }

  // A Ctrl-C during the very first `compose up`, a failed seeder, or a `--no-seed` first run all
  // leave the volume present but the database unseeded. Gating on the volume's existence alone (as
  // this used to) made that state unrecoverable: the next `just up` would see the volume and skip
  // seeding forever. The marker is the only trustworthy signal — it is written after the seeder
  // exits 0, so its absence always means "never successfully seeded".
  const needsSeed = options.fresh || !existsSync(seededMarker);

  const ports = await resolveDevServerPorts(stateDir);
  const { renderedRealm } = await renderAll({ repoRoot: REPO_ROOT, instance, devServerPorts: ports, proxyPort });

  if (!needsSeed) {
    // `needsSeed` is false exactly when Keycloak's database (the same `urbo-cms-data` volume the
    // seeded marker already reasons about) survives from an earlier run — the one condition under
    // which `start-dev --import-realm` silently keeps the realm already in there instead of picking
    // up what was just rendered (see `realm-drift.mjs`). Check before doing anything expensive
    // (pnpm install, the backend image build): a stale realm always means broken login, so there is
    // nothing to gain from discovering that four minutes later.
    const outcome = compareRealmHash({
      storedHash: readStoredRealmHash(instance),
      freshHash: hashRealm(renderedRealm),
    });
    if (outcome === 'drift') {
      throw new Error(realmDriftMessage(instance));
    } else if (outcome === 'bootstrap') {
      // No baseline recorded yet for this instance (predates this check, or `--fresh` cleared it on
      // a run that then failed before reaching the write below). Nothing to compare against, so
      // trust what is presumably already running and record it — see `compareRealmHash`'s comment.
      writeRealmHash(instance, renderedRealm);
    } else {
      // 'ok' — matches what Keycloak already imported. Nothing to do.
    }
  }

  const reattached = await ensureProxy({ repoRoot: REPO_ROOT, proxyPort, exec: run });
  if (reattached.length > 0) {
    console.log(`\nReattached to the recreated shared proxy: ${reattached.join(', ')}`);
    const stale = staleReattachedInstances(reattached, proxyPort);
    const warning = staleReattachedWarning(stale);
    if (warning) {
      console.warn(warning);
    }
  }

  await pnpmInstall();

  // Order is load-bearing, see composeCreateArgs: create (network exists) -> attach the proxy
  // (the public names resolve inside the network) -> start and wait for health.
  await compose(instance, composeCreateArgs(options));
  await attachInstance({ repoRoot: REPO_ROOT, instance, exec: run });
  await startAndWait(instance, options);

  if (needsSeed) {
    // `needsSeed` means Keycloak's database was either just wiped (`--fresh`) or has never finished
    // a `just up` before — in both cases the container that just went healthy in `startAndWait`
    // above imported the realm we rendered for real, so this is the one moment recording it is
    // actually true. This runs regardless of `--no-seed`: the realm import is Keycloak's business,
    // entirely independent of whether the *app's* sample data gets seeded below.
    writeRealmHash(instance, renderedRealm);

    if (options.seed) {
      console.log('\nSeeding sample data…');
      // --force-recreate because this is a one-shot job, not a service: a leftover container from
      // an earlier run holds that run's network id, and after `just reset` recreated the network
      // compose would try to *start* the stale one and fail with "network ... not found". Observed
      // in a real cold-start cycle. Recreating a container that is meant to run once and exit
      // costs nothing.
      await compose(instance, seedArgs());
      writeFileSync(seededMarker, `${new Date().toISOString()}\n`);
    } else {
