  console.log(`\nURLs\n${urlTable(instance, proxyPort)}`);
  const dbPort = await postgresHostPort(instance, run);
  if (dbPort === null) {
    console.log('\nPostgres\n  unavailable');
  } else {
    console.log(`\nPostgres\n${postgresHint(dbPort)}`);
  }

  if (options.detach) {
    console.log('\nDev servers not started (--detach). Run `just serve` to start them.');
    return 0;
  } else {
    console.log('\nStarting dev servers. Ctrl-C stops all of them.\n');
    const handle = await startDevServers({
      repoRoot: REPO_ROOT,
      instance,
      ports,
      selection: options.apps,
      spawnProcess: spawnResolved,
    });
    // If one dev server dies on its own, `just up` must not sit there looking healthy with two of
    // three running, nor exit 0 as if it had been a clean Ctrl-C — `finishDevServers` races the
    // crash against the signals and reports whichever one actually happened.
    return await finishDevServers({ handle });
  }
